SET standard_conforming_strings = ON;
DROP TABLE IF EXISTS "public"."sqldump" CASCADE;
BEGIN;
CREATE TABLE "public"."sqldump"();
ALTER TABLE "public"."sqldump" ADD COLUMN "ogc_fid" SERIAL CONSTRAINT "sqldump_pk" PRIMARY KEY;
SELECT AddGeometryColumn('public','sqldump','wkb_geometry',5186,'MULTIPOLYGON',2);
ALTER TABLE "public"."sqldump" ADD COLUMN "id" NUMERIC(20,0);
ALTER TABLE "public"."sqldump" ADD COLUMN "code" NUMERIC(10,0);
ALTER TABLE "public"."sqldump" ADD COLUMN "area_name" VARCHAR;
ALTER TABLE "public"."sqldump" ADD COLUMN "area_type" VARCHAR;
ALTER TABLE "public"."sqldump" ADD COLUMN "parent_id" NUMERIC(20,0);
CREATE INDEX "sqldump_wkb_geometry_geom_idx" ON "public"."sqldump" USING GIST ("wkb_geometry");
COMMIT;

-- `sqldump` is the staging table produced by QGIS.  Its DONG codes are only
-- unique within their DISTRICT, so the application constraint is (parent_id,
-- code), not code alone. Source IDs are never copied to the application.
BEGIN;

-- DISTRICT rows have no parent in this source dump.  PostgreSQL allows more
-- than one NULL in a composite unique constraint, hence the explicit check.
SELECT
  source.area_type::varchar(16),
  source.code::bigint::varchar(20),
  source.area_name::varchar(100),
  NULL,
  ST_Multi(ST_CollectionExtract(ST_MakeValid(source.wkb_geometry), 3))
FROM public.sqldump AS source
WHERE source.area_type = 'DISTRICT'
  AND NOT ST_IsEmpty(source.wkb_geometry)
  AND NOT EXISTS (
    SELECT 1
    FROM public.administrative_area AS target
    WHERE target.parent_id IS NULL
      AND target.code = source.code::bigint::varchar(20)
  );

-- DONG rows are inserted after their parent district is available.
SELECT
  source_child.area_type::varchar(16),
  source_child.code::bigint::varchar(20),
  source_child.area_name::varchar(100),
  parent.id,
  ST_Multi(ST_CollectionExtract(ST_MakeValid(source_child.wkb_geometry), 3))
FROM public.sqldump AS source_child
JOIN public.sqldump AS source_parent
  ON source_parent.id = source_child.parent_id
JOIN public.administrative_area AS parent
  ON parent.area_type = 'DISTRICT'
  AND parent.parent_id IS NULL
  AND parent.code = source_parent.code::bigint::varchar(20)
WHERE source_child.area_type = 'DONG'
  AND NOT ST_IsEmpty(source_child.wkb_geometry)
ON CONFLICT (parent_id, code) DO UPDATE
SET
  area_type = EXCLUDED.area_type,
  name = EXCLUDED.name,
  geom = EXCLUDED.geom,
  updated_at = now();

COMMIT;
